        "question": "Read the passage. Grade 2 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster.\n\nWhich detail best supports this main idea: Student helpers organized the library so readers could find books faster.",
